/**
 * The one place the generated contract types are named.
 *
 * Everything here comes from `src/lib/api/schema.d.ts`, generated by `pnpm gen:api` from the
 * contract `getpack-api` has committed. Nothing is hand-written: if a shape is not in the
 * contract, it does not exist here (ADR-0006).
 *
 * The seed contract F1.2 built against is gone — getpack-api B1.3 published the real auth
 * surface, `pnpm gen:api --adopt` took it, and the differences came out as type errors,
 * which is exactly what the split was for.
 */

import type { components, paths } from "./schema";

/** Every path this app may call. */
export type ApiPaths = paths;

/** Schema components from the contract. */
export type Schemas = components["schemas"];

/** The token pair every login and refresh endpoint returns (api-conventions §4). */
export type Session = Schemas["TokenPairDto"];
export type TokenSubject = Schemas["TokenSubjectDto"];

/** The signed-in principal, as each surface's `/me` describes them. */
export type CustomerMe = Schemas["StoreMeDto"];
export type StaffMe = Schemas["AdminMeDto"];
export type PartnerMe = Schemas["PartnerMeDto"];

/** One entry in the admin sidebar, built from entitlements rather than role checks (F1 1.3). */
export type MenuEntry = Schemas["MenuEntryDto"];

/** A factory the signed-in partner user may act for, and their roles at it. */
export type FactoryAccess = Schemas["FactoryAccessDto"];

/** The OTP challenge a customer sign-in works from. */
export type OtpChallenge = Schemas["OtpChallengeDto"];

/** A third-party identity linked to a customer account (D-151 LINE, Firebase Google/Apple). */
export type LinkedIdentity = Schemas["LinkedIdentityDto"];
